def digest(data): return "sha256:"+hashlib.sha256(data).hexdigest()
def clean(text): return "\n".join(x.strip() for x in text.replace("\u00ad","").splitlines() if x.strip())
def surface(path,kind):
 if digest(path.read_bytes())!=next(x[3] for x in SOURCES if x[1]==path): raise SystemExit(f"source changed: {path.name}")
 if kind=="html": texts=(clean(BeautifulSoup(path.read_bytes(),"html.parser").get_text("\n")),)
 else: texts=tuple(clean(p.extract_text() or "") for p in PdfReader(path).pages)
 return tuple({"page":i+1,"character_count":len(t),"text_sha256":digest(t.encode())} for i,t in enumerate(texts)),"\n".join(texts)

